args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Apasionadamente dbr:The_Blue_Bead }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1. }
  OPTIONAL { ?director dbp:birthDate ?bd2. }
  BIND(COALESCE(?bd1, ?bd2) AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
} ORDER BY ?film

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
 VALUES ?film { dbr:Apasionadamente dbr:The_Blue_Bead }
 ?film dbo:director ?director .
 OPTIONAL {?director dbo:birthDate ?bd1.}
 OPTIONAL {?director dbp:birthDate ?bd2.}
 OPTIONAL {?director dbp:birth_date ?bd3.}
 OPTIONAL {?director dbp:born ?bd4.}
 OPTIONAL {?director dbp:bornDate ?bd5.}
 OPTIONAL {?director foaf:birthDate ?bd6.}
 BIND(COALESCE(?bd1,?bd2,?bd3,?bd4,?bd5,?bd6) AS ?birthDate)
 OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel)="en") }
 OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel)="en") }
} ORDER BY ?film

SELECT ?film ?filmLabel ?director ?directorLabel ?birthYear WHERE {
  VALUES ?film { dbr:Apasionadamente dbr:The_Blue_Bead }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1. }
  OPTIONAL { ?director dbo:abstract ?abs FILTER(lang(?abs) = "en") }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
  BIND(
    IF(BOUND(?bd1),
       SUBSTR(STR(?bd1), 1, 4),
       REPLACE(STR(?abs), ".*?(\\d{4}).*", "$1")
    ) AS ?birthYear
  )
}
ORDER BY xsd:integer(?birthYear)
LIMIT 10

SELECT ?film ?filmLabel ?director ?directorLabel ?birthYear WHERE {
  VALUES ?film { dbr:Apasionadamente dbr:The_Blue_Bead }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1. }
  OPTIONAL { ?director dbo:abstract ?abs FILTER(lang(?abs) = "en") }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
  BIND(
    IF(BOUND(?bd1),
       SUBSTR(STR(?bd1), 1, 4),
       REPLACE(STR(?abs), ".*?(\\d{4}).*", "$1")
    ) AS ?birthYear
  )
}
ORDER BY xsd:integer(?birthYear)
LIMIT 10

