PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?birthYear WHERE {
  VALUES ?film {
    dbr:Apasionadamente dbr:The_Blue_Bead
  }
  ?film dbo:director ?director .
  OPTIONAL {
    ?director dbo:birthDate ?bd1 .
  }
  OPTIONAL {
    ?director dbo:abstract ?abs
    FILTER(lang(?abs) = "en")
  }
  OPTIONAL {
    ?film rdfs:label ?filmLabel
    FILTER(lang(?filmLabel) = "en")
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(lang(?directorLabel) = "en")
  }
  BIND(IF(BOUND(?bd1) , SUBSTR(STR(?bd1) , 1 , 4) , REPLACE(STR(?abs) , ".*?(\\d{4}).*" , "$1")) AS ?birthYear)
}
ORDER BY xsd:integer(?birthYear)
LIMIT 10

